from flask import Flask, request, jsonify

app = Flask(__name__)

product_stocks = {
    'coke': 20,
    'pepsi': 20,
    'juice': 20,
    'water': 10
}

@app.route('/order', methods=['POST'])
def order():
    product_name = request.form['product_name']
    quantity = int(request.form['quantity'])

    if quantity > 0:
        if product_name in product_stocks:

            if product_stocks[product_name] - quantity < 0:
                return jsonify({'message': 'Not enough stock left!'})

            product_stocks[product_name] -= quantity

            return jsonify({'message': f'Thank you for your purchase of {quantity} {product_name}!'})

        else:
            return jsonify({'message': f'Product "{product_name}" not found. Available products: {list(product_stocks.keys())}'}))

    else:
        return jsonify({'message': 'Invalid quantity!'})

if __name__ == '__main__':
    app.run()

